class Solution {
    public int reverse(int x) {
        int result = 0;
        while (x != 0) {
            int digit = x % 10;
            x /= 10;
            if (result > Integer.MAX_VALUE / 10
                    || (result == Integer.MAX_VALUE / 10 && digit > 7)) {
                return 0;
            }
            if (result < Integer.MIN_VALUE / 10
                    || (result == Integer.MIN_VALUE / 10 && digit < -8)) {
                return 0;
            }
            result = result * 10 + digit;
        }
        return result;
    }
}

class Solution {
    public int reverse(int x) {
        boolean originalNegative = x < 0;
        if (!originalNegative) {
            x = -x;
        }

        int result = 0;
        while (x != 0) {
            int digit = x % 10;
            x /= 10;
            if (result < (Integer.MIN_VALUE - digit) / 10) {
                return 0;
            }
            result = result * 10 + digit;
        }

        if (!originalNegative) {
            if (result == Integer.MIN_VALUE) {
                return 0;
            }
            return -result;
        }
        return result;
    }
}

class Solution {
    public int reverse(int x) {
        boolean negative = x < 0;
        String raw = Integer.toString(x);
        String digits = negative ? raw.substring(1) : raw;
        String reversed = new StringBuilder(digits).reverse().toString();

        int first = 0;
        while (first < reversed.length() - 1 && reversed.charAt(first) == '0') {
            first++;
        }
        reversed = reversed.substring(first);

        String limit = negative ? "2147483648" : "2147483647";
        if (reversed.length() > limit.length()
                || (reversed.length() == limit.length() && reversed.compareTo(limit) > 0)) {
            return 0;
        }

        int result = 0;
        for (int i = 0; i < reversed.length(); i++) {
            int digit = reversed.charAt(i) - '0';
            result = negative ? result * 10 - digit : result * 10 + digit;
        }
        return result;
    }
}

class Solution {
    public int reverse(int x) {
        boolean negative = x < 0;
        int value = x;
        int[] digits = new int[10];
        int count = 0;
        while (value != 0) {
            digits[count++] = Math.abs(value % 10);
            value /= 10;
        }
        if (count == 0) {
            return 0;
        }

        int start = 0;
        while (start < count - 1 && digits[start] == 0) {
            start++;
        }

        int[] limit = negative
                ? new int[] {2, 1, 4, 7, 4, 8, 3, 6, 4, 8}
                : new int[] {2, 1, 4, 7, 4, 8, 3, 6, 4, 7};
        int length = count - start;
        if (length > limit.length) {
            return 0;
        }
        if (length == limit.length) {
            for (int offset = 0; offset < length; offset++) {
                int digit = digits[start + offset];
                if (digit > limit[offset]) {
                    return 0;
                }
                if (digit < limit[offset]) {
                    break;
                }
            }
        }

        int result = 0;
        for (int i = start; i < count; i++) {
            result = negative ? result * 10 - digits[i] : result * 10 + digits[i];
        }
        return result;
    }
}

class Solution {
    public int reverse(int x) {
        int result = 0;
        while (x != 0) {
            int digit = x % 10;
            x /= 10;
            int next = result * 10 + digit;
            if (next / 10 != result) {
                return 0;
            }
            result = next;
        }
        return result;
    }
}
